sys_script.script:
(function executeRule(current, previous) {
    var matId = current.getValue('material_product');
    var locId = current.getValue('location');
    var invType = current.getValue('inventory_type');
    var batchId = current.getValue('batch_lot') || '';
    var isActive = current.getValue('active');

    // Only enforce for active records
    if (isActive != '1' && isActive != 'true' && isActive !== true) {
        return;
    }

    if (!matId || !locId || !invType) {
        return;
    }

    var dup = new GlideRecord('x_2056099_indust_0_inv_stock');
    dup.addQuery('material_product', matId);
    dup.addQuery('location', locId);
    dup.addQuery('inventory_type', invType);
    dup.addQuery('active', true);

    if (batchId) {
        dup.addQuery('batch_lot', batchId);
    } else {
        dup.addNullQuery('batch_lot');
    }

    // Exclude self for safety (in case this is somehow called on update)
    var selfId = current.getValue('sys_id');
    if (selfId) {
        dup.addQuery('sys_id', '!=', selfId);
    }

    dup.setLimit(1);
    dup.query();

    if (dup.hasNext()) {
        var locName = current.getDisplayValue('location') || locId;
        var matName = current.getDisplayValue('material_product') || matId;
        var msg = 'Duplicate stock record: An active inventory record for "' +
                  matName + '" already exists at "' + locName +
                  '" for type "' + invType + '".';
        if (batchId) {
            msg += ' Batch: ' + current.getDisplayValue('batch_lot');
        }
        gs.addErrorMessage(msg);
        current.setAbortAction(true);
    }
})(current, previous);
